// fix-health-app-v2.4.19.cjs — Family Health Track v2.4.19 one-step fix
// Run from the project root (the folder with package.json) with:
//   node fix-health-app-v2.4.19.cjs
// Requires v2.4.18 already applied (run the earlier scripts first if you
// have not run them yet). What it does:
//   1. Backs up each changed file to <file>.bak (first run only)
//   2. Applies the v2.4.19 fix — BMI — မှတ်တမ်းမရှိလည်း Profile အရ ပြမယ်:
//      - Trends / Sidebar / Passport: အရပ်/ကိုယ်အလေးချိန် ထည့်ထားပြီး
//        BMI မှတ်တမ်း မရှိသေးရင် BMI ပေါ်လာမယ် — "Profile အရ
//        တွက်ချက်ထားသည်" လို့ အမှန်အတိုင်း ပြမယ်; ရက်စွဲအတု လုံးဝ
//        မပါဘူး ("ရက်စွဲ မရှိပါ" လို့ပဲ ပြမယ်)
//      - BMI မှတ်တမ်း ရှိရင် မှတ်တမ်းကပဲ အမြဲ အနိုင်ရမယ် — ရက်စွဲနဲ့တကွ
//        ပြမယ်
//      - v2.4.14 မှာ ပါခဲ့တဲ့ Profile အရ BMI ပြခြင်းကို v2.4.16
//        စစ်ဆေးမှုမှာ ဖြုတ်မိခဲ့တာ — အခု အမှန်အတိုင်း တံဆိပ်ကပ်ပြီး
//        ပြန်ထည့်ပေးထားတယ်
//      - မိသားစုဝင် ကြည့်နေတုန်း BMI tab က ပိုင်ရှင် (ကိုယ်တိုင်) ရဲ့
//        အရပ်/အလေးချိန်ကို ယူသုံးမိတာကို ပြင်ထားတယ် — မိသားစုဝင်မှာ
//        မှတ်တမ်းရှိမှသာ ပြမယ်
//   3. Runs npm install, typecheck (tsc), tests (vitest) and build
// Safe to run twice: files already matching the new content are skipped.
// It does NOT touch your data, your Firebase project, or git.
// NOTE: this version does NOT change firestore.rules — nothing to publish
// in the Firebase Console after running.
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const VERSION = '2.4.19';

const DELETED = [];

const FILES = [
  {
    "path": "package.json",
    "b64": ""
  },
  {
    "path": "src/constants/version.ts",
    "b64": "ZXhwb3J0IGNvbnN0IENVUlJFTlRfU1lTVEVNX1ZFUlNJT04gPSAndjIuNC4xOSc7Cg=="
  },
  {
    "path": "src/components/modules/VersionHistoryModal.tsx",
    "b64": ""
  },
  {
    "path": "src/lib/versionCheck.test.ts",
    "b64": ""
  },
  {
    "path": "src/lib/bmiDisplay.ts",
    "b64": ""
  },
  {
    "path": "src/lib/bmiDisplay.test.ts",
    "b64": ""
  },
  {
    "path": "src/components/modules/TrendsOverview.tsx",
    "b64": ""
  },
  {
    "path": "src/components/layout/Sidebar.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/HealthPassportModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/BMIModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminPatientDetail.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminPatientComparison.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminPatientList.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/EditPatientModal.tsx",
    "b64": ""
  }
];

const norm = (s) => String(s).replace(/\r\n/g, '\n');
let applied = 0, skipped = 0, failed = 0;
const failures = [];
function run(cmd, args, label) {
  console.log('  $ ' + cmd + ' ' + args.join(' '));
  const r = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error || r.status !== 0) {
    console.log('[FAIL] ' + label + ' (exit ' + (r.status ?? r.error) + ')');
    return false;
  }
  console.log('[OK] ' + label);
  return true;
}
function main() {
  console.log('Family Health Track fix — v' + VERSION);
  console.log('Project folder: ' + process.cwd());
  const pkgPath = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    console.log('[ERROR] package.json not found here. Run this script from the project root (the folder with package.json).');
    process.exit(1);
  }
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch (e) {
    console.log('[ERROR] package.json could not be read: ' + e.message);
    process.exit(1);
  }
  if (pkg.name !== 'family-health-track') {
    console.log('[ERROR] This does not look like the Family Health Track project (package name: ' + pkg.name + '). Stopping.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.17') {
    console.log('[ERROR] This project is still v2.4.17. Run fix-health-app-v2.4.18.cjs first, then run this script again.');
    process.exit(1);
  }
  if (['2.4.6', '2.4.7', '2.4.8', '2.4.9', '2.4.10', '2.4.11', '2.4.12', '2.4.13', '2.4.14', '2.4.15', '2.4.16'].includes(String(pkg.version))) {
    console.log('[ERROR] This project is still v' + pkg.version + '. Run the v2.4.9, v2.4.10, v2.4.11, v2.4.12, v2.4.13, v2.4.14, v2.4.15, v2.4.16, v2.4.17 and v2.4.18 scripts first (in order), then run this script again.');
    process.exit(1);
  }
  if (!['2.4.18', '2.4.19'].includes(String(pkg.version))) {
    console.log('[ERROR] Unexpected project version ' + pkg.version + ' (expected 2.4.18). Stopping — ask for help before running this.');
    process.exit(1);
  }
  for (const f of FILES) {
    const dest = path.join(process.cwd(), ...f.path.split('/'));
    const next = Buffer.from(f.b64, 'base64').toString('utf8');
    try {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      if (fs.existsSync(dest) && norm(fs.readFileSync(dest, 'utf8')) === norm(next)) {
        console.log('[SKIP] already applied: ' + f.path);
        skipped++;
        continue;
      }
      if (fs.existsSync(dest) && !fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.writeFileSync(dest, next, 'utf8');
      console.log('[OK] applied: ' + f.path);
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + f.path + ': ' + e.message);
      failed++;
      failures.push(f.path + ': ' + e.message);
    }
  }
  for (const rel of DELETED) {
    const dest = path.join(process.cwd(), ...rel.split('/'));
    try {
      if (!fs.existsSync(dest)) {
        console.log('[SKIP] already deleted: ' + rel);
        skipped++;
        continue;
      }
      if (!fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.unlinkSync(dest);
      console.log('[OK] deleted: ' + rel + ' (backup saved as ' + rel + '.bak)');
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + rel + ': ' + e.message);
      failed++;
      failures.push(rel + ': ' + e.message);
    }
  }
  console.log('');
  console.log('Applied ' + applied + ' | Already applied ' + skipped + ' | Failed ' + failed);
  if (failed > 0) {
    console.log('Failures: ' + failures.join(' ; '));
    console.log('Stopping before checks. Your .bak backups are next to the originals.');
    process.exit(1);
  }
  console.log('');
  console.log('--- checks (npm install, typecheck, tests, build) ---');
  const okInstall = run('npm', ['install', '--no-audit', '--no-fund'], 'npm install');
  const okLint = run('npx', ['tsc', '--noEmit'], 'typecheck (tsc --noEmit)');
  const okTest = run('npx', ['vitest', 'run'], 'tests (vitest run)');
  const okBuild = run('npm', ['run', 'build'], 'build (vite build)');
  if (!okInstall || !okLint || !okTest || !okBuild) {
    console.log('');
    console.log('[DONE WITH ERRORS] Files were updated, but a check failed above.');
    console.log('Do NOT deploy yet. Ask for help and include the error lines above.');
    process.exit(1);
  }
  console.log('');
  console.log('[DONE] v' + VERSION + ' applied. Applied ' + applied + ' | Already applied ' + skipped + ' | Failed 0');
  console.log('');
  console.log('NEXT STEPS (အဆင့်လိုက် လုပ်ပါ):');
  console.log('  1. ဒီဗားရှင်းမှာ firestore.rules အပြောင်းအလဲ မရှိဘူး —');
  console.log('     Console မှာ Publish လုပ်စရာ မလိုပါ။');
  console.log('  2. App ကို push / deploy လုပ်ပါ (git push လုပ်ပြီး Cloudflare က');
  console.log('     ပြန် deploy ပါလိမ့်မယ်)။');
  console.log('  3. ဖုန်းမှာ hard-refresh တစ်ခါ လုပ်ပါ။');
  console.log('     Version History မှာ v2.4.19 ပြရပါမယ်။');
  console.log('  4. ဖုန်းမှာ ဒါတွေ စစ်ပါ:');
  console.log('     (1) Trends ဖွင့်ပြီး ဒေါ်စန်းမြင့်ကို ရွေးပါ — BMI ကတ်');
  console.log('         မှာ နံပါတ် ပေါ်ရမယ် + "Profile အရ တွက်ချက်ထားသည်"');
  console.log('         လို့ ပြရမယ် + ရက်စွဲနေရာမှာ "ရက်စွဲ မရှိပါ" ဖြစ်ရမယ်။');
  console.log('     (2) သွေးပေါင်/သကြားကဒ်တွေက အရင်အတိုင်း ရက်စွဲနဲ့တကွ');
  console.log('         မှန်မှန် ပြနေရမယ်။');
  console.log('     (3) BMI tab ဖွင့်ရင် နံပါတ် တူတူ ပြရမယ်။');
  console.log('     (4) Sidebar နဲ့ Health Passport မှာလည်း BMI ပေါ်ရမယ်။');
  console.log('     (5) မိသားစုဝင် တစ်ယောက် ရွေးကြည့်ရင် သူ့မှတ်တမ်းရှိမှ');
  console.log('         BMI ပြရမယ် (ကိုယ်တိုင်ရဲ့ အရပ်/အလေးချိန်နဲ့');
  console.log('         မှားတွက်တာ မရှိရဘူး)။');
}
main();
